const UNIT_GROUPS={
 '압력':{'Pa':1,'kPa':1000,'MPa':1000000,'bar':100000,'kgf/cm²':98066.5,'mmAq':9.80665,'mmHg':133.322},
 '유량':{'m³/s':1,'m³/min':1/60,'m³/h':1/3600,'L/s':0.001,'L/min':0.001/60},
 '풍량':{'m³/s':1,'CMM(m³/min)':1/60,'CMH(m³/h)':1/3600,'L/s':0.001,'CFM(ft³/min)':0.00047194745}
};
function unitOptions(group){return Object.keys(UNIT_GROUPS[group]).map(unit=>`<option value="${E(unit)}">${E(unit)}</option>`).join('')}
async function copyText(value,button){const text=String(value??'');if(!text)return;try{await navigator.clipboard.writeText(text)}catch{const area=document.createElement('textarea');area.value=text;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove()}const original=button.textContent;button.textContent='복사됨';setTimeout(()=>button.textContent=original,1200)}
function openUnitConverter(){const dialog=document.createElement('dialog');dialog.className='reToolDialog reUnitDialog';dialog.innerHTML=`<div class="reToolDialogBody"><div class="reToolDialogHead"><div><h3>단위환산기</h3><p>압력·유량·풍량 단위를 선택하면 자동으로 환산됩니다.</p></div><button type="button" data-dialog-close aria-label="닫기">×</button></div><div class="reConverterGrid"><label>환산대상<select data-convert-group>${Object.keys(UNIT_GROUPS).map(value=>`<option>${value}</option>`).join('')}</select></label><label>입력단위<select data-convert-from>${unitOptions('압력')}</select></label><label>환산단위<select data-convert-to>${unitOptions('압력')}</select></label><label class="reConverterValue">입력단위값<input type="number" step="any" inputmode="decimal" data-convert-value placeholder="값을 입력하세요"></label><label class="reConverterResult">환산결과<div><output data-convert-result>0</output><button type="button" data-convert-copy>복사</button></div></label></div><div class="reDialogFooter"><button type="button" data-dialog-close>닫기</button></div></div>`;document.body.appendChild(dialog);const group=dialog.querySelector('[data-convert-group]'),from=dialog.querySelector('[data-convert-from]'),to=dialog.querySelector('[data-convert-to]'),value=dialog.querySelector('[data-convert-value]'),result=dialog.querySelector('[data-convert-result]');function calculate(){const input=Number(value.value);if(!Number.isFinite(input)){result.value='0';return}const factors=UNIT_GROUPS[group.value],converted=input*factors[from.value]/factors[to.value];result.value=Number.isFinite(converted)?Number(converted.toPrecision(12)).toString():'0'}function refreshUnits(){from.innerHTML=unitOptions(group.value);to.innerHTML=unitOptions(group.value);to.selectedIndex=Math.min(1,to.options.length-1);calculate()}group.onchange=refreshUnits;from.onchange=calculate;to.onchange=calculate;value.oninput=calculate;dialog.querySelector('[data-convert-copy]').onclick=event=>copyText(result.value,event.currentTarget);dialog.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove(),{once:true});refreshUnits();dialog.showModal()}
function calculateExpression(expression){const normalized=String(expression).replace(/×/g,'*').replace(/÷/g,'/').replace(/−/g,'-');if(!normalized||!/^[0-9+\-*/().\s]+$/.test(normalized))return '오류';try{const value=Function(`"use strict";return (${normalized})`)();return Number.isFinite(value)?Number(value.toPrecision(12)).toString():'오류'}catch{return '오류'}}
function openCalculator(){const dialog=document.createElement('dialog');dialog.className='reToolDialog reCalculatorDialog';const keys=['C','⌫','(',')','7','8','9','÷','4','5','6','×','1','2','3','−','0','.','+','='];dialog.innerHTML=`<div class="reToolDialogBody"><div class="reToolDialogHead"><div><h3>계산기</h3><p>계산 결과를 복사하여 측정값 칸에 붙여넣을 수 있습니다.</p></div><button type="button" data-dialog-close aria-label="닫기">×</button></div><input class="reCalcDisplay" data-calc-display value="" inputmode="decimal" aria-label="계산식"><output class="reCalcResult" data-calc-result>0</output><div class="reCalcKeys">${keys.map(key=>`<button type="button" data-calc-key="${key}" class="${key==='='?'equals':''}">${key}</button>`).join('')}</div><button type="button" class="reCalcCopy" data-calc-copy>결과 복사</button><div class="reDialogFooter"><button type="button" data-dialog-close>닫기</button></div></div>`;document.body.appendChild(dialog);const display=dialog.querySelector('[data-calc-display]'),result=dialog.querySelector('[data-calc-result]');dialog.querySelectorAll('[data-calc-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.calcKey;if(key==='C'){display.value='';result.value='0'}else if(key==='⌫')display.value=display.value.slice(0,-1);else if(key==='=')result.value=calculateExpression(display.value);else display.value+=key});display.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();result.value=calculateExpression(display.value)}};dialog.querySelector('[data-calc-copy]').onclick=event=>copyText(result.value,event.currentTarget);dialog.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();display.focus()}
