function currentItem(e){return e?.items.length?Math.min(Math.max(itemPositions.get(e.uid)||0,0),e.items.length-1):0}
function pager(e,i){return `<div class="rePager"><button type="button" data-step="-1" ${i===0?'disabled':''} aria-label="이전 점검항목">‹ 이전</button><span role="status" aria-live="polite">${E(e.number)} · ${i+1} / ${e.items.length}</span><button type="button" data-step="1" ${i>=e.items.length-1?'disabled':''} aria-label="다음 점검항목">다음 ›</button></div>`}
function moveItem(step){const e=equip();if(!e)return;const next=currentItem(e)+step;if(next<0||next>=e.items.length)return;itemPositions.set(e.uid,next);render();const panel=document.getElementById('reSwipePage');panel?.scrollIntoView({block:'start',behavior:'auto'});panel?.focus({preventScroll:true})}
function swipeStep(dx,dy){return Math.abs(dx)>=70&&Math.abs(dx)>Math.abs(dy)*1.6?(dx<0?1:-1):0}
function bindPager(){
 root().querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>moveItem(Number(el.dataset.step)));
 const panel=document.getElementById('reSwipePage');if(!panel)return;
 let start=null;
 const isEditing=el=>el.closest('input,textarea,select,button,a,summary,[contenteditable="true"]');
 panel.addEventListener('pointerdown',ev=>{if(!ev.isPrimary||ev.pointerType==='mouse'||isEditing(ev.target)){start=null;return}start={x:ev.clientX,y:ev.clientY,id:ev.pointerId}});
 panel.addEventListener('pointerup',ev=>{if(!start||ev.pointerId!==start.id)return;const step=swipeStep(ev.clientX-start.x,ev.clientY-start.y);start=null;if(step)moveItem(step)});
 panel.addEventListener('pointercancel',()=>{start=null});
 panel.addEventListener('keydown',ev=>{if(isEditing(ev.target))return;if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){ev.preventDefault();moveItem(ev.key==='ArrowRight'?1:-1)}});
}

