function sortEquipmentList(){const typeOrder=new Map(Object.keys(CHECK_TEMPLATES).map((type,index)=>[type,index]));d.equipment.sort((a,b)=>{const typeDifference=(typeOrder.get(a.type)??Number.MAX_SAFE_INTEGER)-(typeOrder.get(b.type)??Number.MAX_SAFE_INTEGER);if(typeDifference)return typeDifference;const typeNameDifference=equipmentNumberCollator.compare(String(a.type||''),String(b.type||''));if(typeNameDifference)return typeNameDifference;return equipmentNumberCollator.compare(String(a.number||''),String(b.number||''))})}
const actions={add(){const type=document.getElementById('reType').value,numbers=document.getElementById('reNumbers').value.split(/[,，\n]/).map(v=>v.trim()).filter(Boolean);if(!numbers.length)return alert('실제 설비번호를 입력하세요.');if(new Set(numbers).size!==numbers.length||numbers.some(n=>d.equipment.some(e=>e.number===n)))return alert('중복 설비번호가 있습니다. 번호를 확인하세요.');for(const number of numbers){let e={uid:crypto.randomUUID(),type,number,items:CHECK_TEMPLATES[type].map(x=>({...x,result:'미작성',photos:['','',''],reason0:'',reason1:defaultReason(x,'reason1'),reason2:defaultReason(x,'reason2'),measurement:'',action:''}))};d.equipment.push(e);selected=e.uid}sortEquipmentList();save();render()},remove(){if(!confirm('이 설비의 사진과 점검 기록을 삭제할까요?'))return;const removed=selected;d.equipment=d.equipment.filter(e=>e.uid!==removed);equipmentDeleteSelection.delete(removed);equipmentViews.delete(removed);selected=d.equipment[0]?.uid||'';save();render()},backup(){download(JSON.stringify(d),fileName()+'.json','application/json')},preview(){preview()},excel(){exportInspectionExcel()}};
function fileName(){return (d.info['현장명']||'성능점검보고서').replace(/[\\/:*?"<>|]/g,'_')}
function download(data,name,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}

function resultMark(result){return result==='적합'?'○':(['미흡','조치필요'].includes(result)?'×':result==='해당없음'?'/':result==='측정불가'?'△':'')}
function safeSheetName(value,fallback){const name=String(value||fallback).replace(/[\\/*?:\[\]]/g,' ').trim();return (name||fallback).slice(0,31)}
function styleExcelRange(ws,range,options={}){const border={style:'thin',color:{argb:'FF707070'}};ws.getCell(range.split(':')[0]);ws.eachRow({includeEmpty:true},(row,rowNumber)=>{if(rowNumber<options.minRow||rowNumber>options.maxRow)return;row.eachCell({includeEmpty:true},(cell,colNumber)=>{if(colNumber<options.minCol||colNumber>options.maxCol)return;cell.font={name:'Malgun Gothic',size:options.fontSize||9,bold:false,color:{argb:'FF111111'}};cell.alignment={vertical:'middle',horizontal:'left',wrapText:true};cell.border={top:border,left:border,bottom:border,right:border}})})}
async function excelPhotoData(dataUrl,width=900,height=560){if(!dataUrl)return null;return new Promise(resolve=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,width,height);context.drawImage(image,0,0,width,height);resolve({base64:canvas.toDataURL('image/jpeg',.9),extension:'jpeg'})};image.onerror=()=>resolve(null);image.src=dataUrl})}
async function addExcelPhoto(wb,ws,dataUrl,range,width=900,height=560){const photo=await excelPhotoData(dataUrl,width,height);if(!photo)return;const imageId=wb.addImage(photo);ws.addImage(imageId,range)}
function setupExcelSheet(ws){ws.properties.defaultRowHeight=18;ws.pageSetup={paperSize:9,orientation:'portrait',fitToPage:true,fitToWidth:1,fitToHeight:1,margins:{left:0.3,right:0.3,top:0.45,bottom:0.45,header:0.15,footer:0.15},horizontalCentered:true};ws.headerFooter={oddHeader:'&L기계설비 성능점검 결과보고서&RII. 기계설비 성능점검 결과보고서',oddFooter:'&C&P / &N'};ws.views=[{showGridLines:false}];[5,10,10,10,10,10,10,10,5].forEach((width,index)=>ws.getColumn(index+1).width=width)}
