async function buildExcelSummary(wb,e,equipmentIndex){const ws=wb.addWorksheet(safeSheetName(`${e.number}_요약`,`설비${equipmentIndex+1}_요약`));setupExcelSheet(ws);fillExcelTitle(ws,`${e.type} 성능점검표`);const fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFE2EED9'}};ws.mergeCells('A4:B5');ws.getCell('A4').value='점검자';ws.mergeCells('C4:E5');ws.getCell('C4').value=e['점검자']||d.info['점검자']||'';ws.mergeCells('F4:G4');ws.getCell('F4').value='설비번호';ws.mergeCells('H4:I4');ws.getCell('H4').value=e.number;ws.mergeCells('F5:G5');ws.getCell('F5').value='설치위치 (No.)';ws.mergeCells('H5:I5');ws.getCell('H5').value=e['설치위치']||'';['A4','F4','F5'].forEach(address=>ws.getCell(address).fill=fill);ws.mergeCells('A7:A'+(6+e.items.length));ws.getCell('A7').value='점검\n항목';e.items.forEach((item,index)=>{const row=7+index;ws.mergeCells(row,2,row,8);ws.getCell(row,2).value=item.title;ws.getCell(row,9).value=resultMark(item.result);ws.getCell(row,9).alignment={horizontal:'center',vertical:'middle'}});const actionStart=8+e.items.length;ws.mergeCells(actionStart,1,actionStart+3,1);ws.getCell(actionStart,1).value='조치\n사항';ws.mergeCells(actionStart,2,actionStart+1,9);ws.getCell(actionStart,2).value='< 미흡사항 >\n'+e.items.filter(item=>item.result==='미흡').map(item=>item.title).join(', ');ws.mergeCells(actionStart+2,2,actionStart+3,9);ws.getCell(actionStart+2,2).value='< 조치필요사항 >\n'+e.items.filter(item=>item.result==='조치필요').map(item=>`${item.title} ${item.action||''}`).join('\n');const photoRow=actionStart+4;ws.mergeCells(photoRow,1,photoRow+10,1);ws.getCell(photoRow,1).value='현장\n사진';ws.mergeCells(photoRow,2,photoRow+10,9);const representative=e.items.flatMap(item=>item.photos||[]).find(Boolean);if(representative)await addExcelPhoto(wb,ws,representative,{tl:{col:1.05,row:photoRow-0.9},br:{col:8.95,row:photoRow+9.9},editAs:'oneCell'});const noteRow=photoRow+11;ws.mergeCells(noteRow,1,noteRow+1,1);ws.getCell(noteRow,1).value='비고';ws.mergeCells(noteRow,2,noteRow+1,9);ws.getCell(noteRow,2).value=e['측정값']||'';const methodRow=noteRow+3;ws.mergeCells(methodRow,1,methodRow,9);ws.getCell(methodRow,1).value='작성방법';ws.getCell(methodRow,1).fill=fill;ws.getCell(methodRow,1).alignment={horizontal:'center',vertical:'middle'};ws.mergeCells(methodRow+1,1,methodRow+5,9);ws.getCell(methodRow+1,1).value='1. 유지관리지침서 및 대상 현황표와의 적합 여부를 참고하여 작성합니다.\n2. 점검결과에는 적합 ○, 조치필요 ×, 해당없음 /을 표기합니다.\n3. 현황사진에는 측정사진 및 측정데이터를 포함하여 첨부합니다.\n4. 전체 수량의 50% 이상 범위에서 점검을 실시합니다.';styleExcelRange(ws,'A4:I'+(methodRow+5),{minRow:4,maxRow:methodRow+5,minCol:1,maxCol:9,fontSize:9});['A4','F4','F5','A7',ws.getCell(actionStart,1).address,ws.getCell(photoRow,1).address,ws.getCell(noteRow,1).address].forEach(address=>{ws.getCell(address).fill=fill;ws.getCell(address).font={name:'Malgun Gothic',size:9,bold:true};ws.getCell(address).alignment={horizontal:'center',vertical:'middle',wrapText:true}});ws.pageSetup.printArea=`A1:I${methodRow+5}`}
async function buildExcelItem(wb,e,item,itemIndex,equipmentIndex){const suffix=String(itemIndex+1).padStart(2,'0'),ws=wb.addWorksheet(safeSheetName(`${e.number}_${suffix}`,`설비${equipmentIndex+1}_${suffix}`));setupExcelSheet(ws);fillExcelTitle(ws,item.title);const fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFE2EED9'}};ws.mergeCells('A4:B4');ws.getCell('A4').value='구분';ws.mergeCells('C4:I4');ws.getCell('C4').value='점검내용';ws.mergeCells('A5:B12');ws.getCell('A5').value='점검\n방법·기준';ws.mergeCells('C5:I12');ws.getCell('C5').value=item.criteria||'';ws.mergeCells('A13:C13');ws.getCell('A13').value='현황 사진';ws.mergeCells('D13:F13');ws.getCell('D13').value='적합';ws.mergeCells('G13:I13');ws.getCell('G13').value='미흡사항';[['A14:C29',item.photos?.[0]],['D14:F29',item.photos?.[1]],['G14:I29',item.photos?.[2]]].forEach(([range])=>ws.mergeCells(range));await addExcelPhoto(wb,ws,item.photos?.[0],{tl:{col:0.05,row:13.05},br:{col:2.95,row:28.95},editAs:'oneCell'});await addExcelPhoto(wb,ws,item.photos?.[1],{tl:{col:3.05,row:13.05},br:{col:5.95,row:28.95},editAs:'oneCell'});await addExcelPhoto(wb,ws,item.photos?.[2],{tl:{col:6.05,row:13.05},br:{col:8.95,row:28.95},editAs:'oneCell'});ws.mergeCells('A30:C35');ws.getCell('A30').value='';ws.mergeCells('D30:F35');ws.getCell('D30').value='사유 : '+reasonValue(item,'reason1');ws.mergeCells('G30:I35');ws.getCell('G30').value='사유 : '+reasonValue(item,'reason2');ws.mergeCells('A36:B39');ws.getCell('A36').value='측정값 /\n확인내용';ws.mergeCells('C36:I39');ws.getCell('C36').value=item.measurement||'';ws.mergeCells('A40:B44');ws.getCell('A40').value='조치사항';ws.mergeCells('C40:I44');ws.getCell('C40').value=item.action||'';styleExcelRange(ws,'A4:I44',{minRow:4,maxRow:44,minCol:1,maxCol:9,fontSize:String(item.criteria||'').length>600?7:9});['A4','C4','A5','A13','D13','G13','A36','A40'].forEach(address=>{ws.getCell(address).fill=fill;ws.getCell(address).font={name:'Malgun Gothic',size:9,bold:true};ws.getCell(address).alignment={horizontal:'center',vertical:'middle',wrapText:true}});for(let row=14;row<=29;row++)ws.getRow(row).height=16;ws.pageSetup.printArea='A1:I44'}
async function exportInspectionExcel(){if(!d.equipment.length)return alert('먼저 성능점검표에서 설비와 점검내용을 등록하세요.');if(!window.ExcelJS)return alert('사진 포함 Excel 출력 구성요소를 불러오지 못했습니다. 인터넷 연결 후 다시 시도하세요.');try{status('사진 포함 Excel 점검표를 만드는 중…');const wb=new ExcelJS.Workbook();wb.creator='기계설비 성능점검';wb.created=new Date();for(let equipmentIndex=0;equipmentIndex<d.equipment.length;equipmentIndex++){const e=d.equipment[equipmentIndex];await buildExcelSummary(wb,e,equipmentIndex);for(let itemIndex=0;itemIndex<e.items.length;itemIndex++)await buildExcelItem(wb,e,e.items[itemIndex],itemIndex,equipmentIndex)}const buffer=await wb.xlsx.writeBuffer();download(buffer,`${fileName()}_성능점검표.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');status('사진 포함 Excel 점검표 출력 완료')}catch(error){console.error(error);status('Excel 점검표 출력 실패');alert('Excel 점검표를 만들지 못했습니다.\n\n'+(error?.message||error))}}
async function buildExcelVacuumSupplement(wb,e,item,itemIndex,equipmentIndex){const suffix=String(itemIndex+1).padStart(2,'0'),ws=wb.addWorksheet(safeSheetName(`${e.number}_${suffix}_진공펌프`,`설비${equipmentIndex+1}_진공펌프`));setupExcelSheet(ws);fillExcelTitle(ws,'진공펌프 현황·적합·미흡사항 사진');const fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFE2EED9'}};ws.mergeCells('A4:C4');ws.getCell('A4').value='진공펌프 현황사진';ws.mergeCells('D4:F4');ws.getCell('D4').value='진공펌프 적합 사진';ws.mergeCells('G4:I4');ws.getCell('G4').value='진공펌프 미흡사항 사진';[['A5:C28',item.photos?.[3],0.05,2.95],['D5:F28',item.photos?.[4],3.05,5.95],['G5:I28',item.photos?.[5],6.05,8.95]].forEach(([range])=>ws.mergeCells(range));await addExcelPhoto(wb,ws,item.photos?.[3],{tl:{col:0.05,row:4.05},br:{col:2.95,row:27.95},editAs:'oneCell'});await addExcelPhoto(wb,ws,item.photos?.[4],{tl:{col:3.05,row:4.05},br:{col:5.95,row:27.95},editAs:'oneCell'});await addExcelPhoto(wb,ws,item.photos?.[5],{tl:{col:6.05,row:4.05},br:{col:8.95,row:27.95},editAs:'oneCell'});styleExcelRange(ws,'A4:I28',{minRow:4,maxRow:28,minCol:1,maxCol:9,fontSize:9});['A4','D4','G4'].forEach(address=>{ws.getCell(address).fill=fill;ws.getCell(address).font={name:'Malgun Gothic',size:9,bold:true};ws.getCell(address).alignment={horizontal:'center',vertical:'middle',wrapText:true}});for(let row=5;row<=28;row++)ws.getRow(row).height=22;ws.pageSetup.printArea='A1:I28'}
const buildExcelItemWithoutVacuum=buildExcelItem;buildExcelItem=async function(wb,e,item,itemIndex,equipmentIndex){await buildExcelItemWithoutVacuum(wb,e,item,itemIndex,equipmentIndex);if(isVacuumPumpItem(e,item))await buildExcelVacuumSupplement(wb,e,item,itemIndex,equipmentIndex)};

function usePhoneCamera(n=navigator){return !!(n.userAgentData?.mobile||/Android|iPhone|iPad|iPod/i.test(n.userAgent)||(n.platform==='MacIntel'&&n.maxTouchPoints>1))}
function openPhotoPicker(slot){
 const target=equip(),index=slot.dataset.photoSlot,isEquipmentPhoto=slot.hasAttribute('data-equipment-photo');
 const dlg=document.createElement('dialog');dlg.className='rePhotoDialog';
 dlg.innerHTML=`<div class="rePhotoDialogBody"><h3>사진 첨부</h3><p>해당 칸에 넣을 사진을 선택하세요.</p><button type="button" data-source="gallery">사진 선택 · 갤러리 / 파일</button><button type="button" data-source="camera">카메라로 촬영</button><div class="reCamera" hidden><video autoplay muted playsinline></video><button type="button" data-shutter disabled>촬영하여 첨부</button></div><p role="status" class="reCameraMessage"></p><button type="button" data-close>취소</button></div>`;
 document.body.appendChild(dlg);let stream=null,closed=false;
 function cleanup(){closed=true;stream?.getTracks().forEach(t=>t.stop());dlg.remove();if(slot.isConnected)slot.focus()}
 dlg.addEventListener('close',cleanup,{once:true});dlg.querySelector('[data-close]').onclick=()=>dlg.close();
 function choose(capture){const input=document.createElement('input');input.type='file';input.accept='image/*';input.hidden=true;if(capture)input.setAttribute('capture','environment');dlg.appendChild(input);input.onchange=()=>{const f=input.files[0];if(!f){input.remove();return}(isEquipmentPhoto?equipmentPhoto:photo)({files:[f],dataset:{photo:index}},target);dlg.close()};input.addEventListener('cancel',()=>input.remove(),{once:true});input.click()}
 dlg.querySelector('[data-source="gallery"]').onclick=()=>choose(false);
 if(usePhoneCamera()){
  dlg.querySelector('[data-source="camera"]').textContent='휴대폰 카메라로 촬영';
  dlg.querySelector('.reCameraMessage').textContent='휴대폰 촬영 화면에서 방향과 줌을 조절한 뒤 사진 사용 또는 완료를 선택하세요.';
 }
 dlg.querySelector('[data-source="camera"]').onclick=async()=>{
  if(usePhoneCamera()){choose(true);return} 
  const msg=dlg.querySelector('.reCameraMessage');
  if(!navigator.mediaDevices?.getUserMedia){msg.textContent='이 환경에서는 카메라를 열 수 없습니다. HTTPS로 접속하거나 사진 선택을 이용하세요.';return}
  const cam=dlg.querySelector('[data-source="camera"]');cam.disabled=true;msg.textContent='카메라 연결 중…';
  try{const incoming=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});if(closed){incoming.getTracks().forEach(t=>t.stop());return}stream=incoming;const video=dlg.querySelector('video');video.muted=true;video.autoplay=true;video.playsInline=true;video.setAttribute('webkit-playsinline','');video.srcObject=stream;dlg.querySelector('.reCamera').hidden=false;
   await cameraPreviewReady(video,()=>closed);
   if(closed)return;dlg.querySelector('[data-shutter]').disabled=false;msg.textContent='영상이 보이는지 확인한 뒤 촬영하여 첨부를 누르세요.';
  }catch(err){stream?.getTracks().forEach(t=>t.stop());if(!closed){dlg.querySelector('[data-shutter]').disabled=true;dlg.querySelector('.reCamera').hidden=true;const messages={NotAllowedError:'카메라 사용이 허용되지 않았습니다. 브라우저의 사이트 카메라 권한을 허용해 주세요.',NotFoundError:'사용할 수 있는 카메라를 찾지 못했습니다.',NotReadableError:'카메라를 사용할 수 없습니다. 다른 촬영 앱을 닫고 다시 시도해 주세요.',PreviewTimeout:'카메라 영상이 도착하지 않았습니다. 다시 시도하거나 기본 카메라 앱으로 촬영 후 사진 선택으로 첨부해 주세요.'};msg.textContent=messages[err.name]||'카메라를 열지 못했습니다. 권한과 연결을 확인하거나 사진 선택으로 첨부해 주세요.';cam.disabled=false;cam.textContent='카메라 다시 연결'}}
 };
 dlg.querySelector('[data-shutter]').onclick=()=>{const video=dlg.querySelector('video');if(!video.videoWidth)return;const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{if(!blob||closed)return;(isEquipmentPhoto?equipmentPhoto:photo)({files:[blob],dataset:{photo:index}},target);dlg.close()},'image/jpeg',.9)};
 dlg.showModal();
}

function cameraPreviewReady(video,isClosed){
 return new Promise((resolve,reject)=>{
  let done=false,timer;
  function finish(error){if(done)return;done=true;clearInterval(timer);error?reject(error):resolve()}
  const started=Date.now();
  timer=setInterval(()=>{if(isClosed())return finish(Object.assign(new Error('닫힘'),{name:'AbortError'}));if(video.readyState>=2&&video.videoWidth>0&&video.videoHeight>0&&!video.paused)return finish();if(Date.now()-started>12000)finish(Object.assign(new Error('영상 대기 시간 초과'),{name:'PreviewTimeout'}))},100);
  video.play().catch(finish);
 });
}

function savePhotoInBackground(message){render();status(message);save().catch(error=>{console.error('사진 저장 실패',error);status('사진 저장 실패 · 다시 촬영하거나 백업을 내려받으세요.')})}
async function photo(el,target=equip()){const f=el.files[0];if(!f)return;const e=target,[i,j]=el.dataset.photo.split(':').map(Number);try{const bm=await createImageBitmap(f,{imageOrientation:'from-image'}),scale=Math.min(1,1600/Math.max(bm.width,bm.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bm.width*scale);canvas.height=Math.round(bm.height*scale);canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);e.items[i].photos[j]=canvas.toDataURL('image/jpeg',.85);bm.close();savePhotoInBackground('사진이 첨부되었습니다 · 저장 중…')}catch(err){alert('사진을 처리하지 못했습니다. JPG 또는 PNG 파일과 저장공간을 확인하세요.')}}
async function equipmentPhoto(el,target=equip()){const f=el.files[0];if(!f||!target)return;try{const bm=await createImageBitmap(f,{imageOrientation:'from-image'}),scale=Math.min(1,1800/Math.max(bm.width,bm.height)),canvas=document.createElement('canvas');canvas.width=Math.round(bm.width*scale);canvas.height=Math.round(bm.height*scale);canvas.getContext('2d').drawImage(bm,0,0,canvas.width,canvas.height);target.sitePhoto=canvas.toDataURL('image/jpeg',.88);bm.close();savePhotoInBackground('현장사진이 첨부되었습니다 · 저장 중…')}catch(err){alert('현장사진을 처리하지 못했습니다. JPG 또는 PNG 파일과 저장공간을 확인하세요.')}}
async function restore(ev){try{const v=JSON.parse(await ev.target.files[0].text());if(v.version!==2||!v.info||!Array.isArray(v.equipment)||!Array.isArray(v.energy)||v.equipment.some(e=>!e.uid||!e.number||!e.type||!Array.isArray(e.items)||e.items.some(i=>!Array.isArray(i.photos)||i.photos.some(p=>p&&!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p)))))throw Error();if(!confirm('현재 작성 내용을 백업 파일로 교체할까요?'))return;d=v;selected=d.equipment[0]?.uid||'';await save();render()}catch(e){alert('올바른 보고서 백업 파일인지 확인하세요.')}}
function table(rows){return '<table>'+rows.map(r=>'<tr>'+r.map(v=>'<td>'+E(v).replace(/\n/g,'<br>')+'</td>').join('')+'</tr>').join('')+'</table>'}
function textSections(n){return fields[n].map(k=>'<h3>'+E(k)+'</h3><p>'+E(d.info[k]||'미입력').replace(/\n/g,'<br>')+'</p>').join('')}
function page(title,content){return `<section class="paper"><div class="paperhead">${E(d.info['현장명']||'현장명 미입력')} · 기계설비 성능점검 보고서</div><h2>${title}</h2>${content}</section>`}
function report(){let html=page('기계설비 성능점검 보고서',table(fields[0].filter(k=>k!=='제출문').map(k=>[k,d.info[k]||'미입력'])));html+=page('점검완료 제출문','<p>'+E(d.info['제출문']||'미입력').replace(/\n/g,'<br>')+'</p>');html+=page('목차','<ol>'+titles.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol>');html+=page('Ⅰ. 성능점검 계획서',textSections(1)+ '<h3>점검대상 기계설비 수량</h3>'+table([['설비종류','등록대수'],...Object.keys(CHECK_TEMPLATES).filter(t=>d.equipment.some(e=>e.type===t)).map(t=>[t,d.equipment.filter(e=>e.type===t).length])])+'<h3>설비 현황</h3>'+table([['종류','번호','용도','설치위치'],...d.equipment.map(e=>[e.type,e.number,e['용도'],e['설치위치']]) ]));html+=page('Ⅱ. 성능점검 결과보고서',textSections(2)+table([['종류','번호','전체항목','작성항목','미흡·조치필요'],...d.equipment.map(e=>[e.type,e.number,e.items.length,e.items.filter(i=>i.result!=='미작성').length,e.items.filter(i=>['미흡','조치필요'].includes(i.result)).length]) ]));for(const e of d.equipment){html+=page(`Ⅲ. ${E(e.type)} 성능점검표 · ${E(e.number)}`,table([['설비번호',e.number],...['용도','설치위치','제조사','설치년도','사양','점검일','점검자','측정값'].map(k=>[k,e[k]||'미입력'])])+table([['점검항목','판정'],...e.items.map(i=>[i.title,i.result])]));for(const i of e.items){html+=page(`${E(e.type)} · ${E(e.number)} / ${E(i.title)}`,table([['점검방법·기준',i.criteria],['판정',i.result],['측정값·확인내용',i.measurement||'미입력']])+`<div class="photos">${['현황','적합','미흡사항'].map((name,j)=>`<section><h4>${name} 사진</h4>${i.photos[j]?`<div class="reportPhotoFrame"><img src="${i.photos[j]}" alt="${name}"></div>`:'<div class="noPhoto">사진 미첨부</div>'}<p>사유: ${E(i['reason'+j]||'미입력').replace(/\n/g,'<br>')}</p></section>`).join('')}</div>`+table([['조치사항',i.action||'미입력']]))}}html+=page('Ⅳ. 기계설비 시스템 검토',textSections(4));html+=page('Ⅴ. 성능개선 계획 수립',textSections(5)+table([['설비번호','점검항목','판정','조치사항'],...d.equipment.flatMap(e=>e.items.filter(i=>['미흡','조치필요'].includes(i.result)).map(i=>[e.number,i.title,i.result,i.action]))]));html+=page('Ⅵ. 에너지사용량 분석',textSections(6).split('<h3>에너지 절감 방안</h3>')[0]+table([['월','사용량'],...Array.from({length:12},(_,i)=>[i+1,d.energy[i]??'미입력']),['입력월 합계',d.energy.reduce((s,x)=>s+(Number(x)||0),0)]]));html+=page('Ⅶ. 에너지 절감 방안','<p>'+E(d.info['에너지 절감 방안']||'미입력').replace(/\n/g,'<br>')+'</p>');return html}
function preview(){const w=window.open('','_blank');if(!w)return alert('팝업을 허용한 뒤 다시 시도하세요.');w.document.write(`<!doctype html><html lang="ko"><meta charset="utf-8"><title>${E(fileName())}</title><style>body{font-family:Arial,'Malgun Gothic',sans-serif;background:#e9edf2;color:#111;line-height:1.45}.paper{box-sizing:border-box;background:white;width:210mm;min-height:297mm;margin:20px auto;padding:14mm 16mm 12mm;break-after:page;position:relative}.paperhead{font-size:10px;border:0;display:flex;justify-content:space-between}.paperhead:after{content:'II. 기계설비 성능점검 결과보고서'}h2{font-size:22px;margin:22px 0}h3{font-size:16px}table{border-collapse:collapse;width:100%;margin:13px 0;table-layout:fixed}td{border:1px solid #777;padding:6px;white-space:pre-wrap;overflow-wrap:anywhere;vertical-align:top}td:first-child{background:#e4eedc;width:28%}tr{break-inside:avoid}.photos{display:grid;grid-template-columns:repeat(3,1fr);gap:0;break-inside:avoid}.photos section{border:1px solid #777;min-width:0}.photos h4{margin:0;text-align:center;background:#e4eedc}.reportPhotoFrame{box-sizing:border-box;width:100%;height:190px;padding:2px;background:#fff;overflow:hidden}.photos .reportPhotoFrame img{display:block;box-sizing:border-box;width:100%;height:100%;margin:0;padding:0;object-fit:fill;border:0;border-radius:0}.noPhoto{width:100%;height:190px;display:grid;place-items:center;color:#aaa}.photos p{padding:8px;overflow-wrap:anywhere}.tools{position:sticky;top:0;z-index:5;background:#183e63;color:#fff;padding:12px}button{padding:10px}p{white-space:pre-wrap;overflow-wrap:anywhere}.officialTitle{text-align:center;font-size:23px;margin:14px 0 8px}.officialMeta,.officialGrid,.officialSummary{border-collapse:collapse;width:100%;table-layout:fixed;margin:0}.officialMeta th,.officialMeta td,.officialGrid th,.officialGrid td,.officialSummary th,.officialSummary td{border:1px solid #666;padding:5px;background:#fff;font-size:10.5px;vertical-align:middle}.officialMeta th,.officialGrid th,.officialSummary th{background:#e4eedc;text-align:center;font-weight:500}.officialSummary td:first-child,.officialGrid td:first-child,.officialMeta td:first-child{width:auto;background:#fff}.officialSummary .group{background:#e4eedc;text-align:center;font-weight:600}.officialSummary .mark{text-align:center;font-size:15px}.officialAction{border:1px solid #666;border-top:0;min-height:38px;padding:6px;font-size:10px}.officialRepresentative{border:1px solid #666;border-top:0;height:150px;padding:2px}.officialRepresentative img,.officialPhoto img{display:block;width:100%;height:100%;object-fit:fill}.officialNotes{border:1px solid #666;margin-top:6px;font-size:9px;padding:5px}.officialItemTitle{font-size:16px;margin:12px 0 8px}.officialCriteria{height:126px;white-space:pre-wrap;font-size:9.5px;line-height:1.35}.officialCriteria.long{font-size:7.5px;line-height:1.17}.officialPhotoGrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-top:14px}.officialPhotoCell{border:1px solid #666;border-right:0;display:grid;grid-template-rows:24px 180px minmax(58px,auto);min-width:0}.officialPhotoCell:last-child{border-right:1px solid #666}.officialPhotoCell h4{margin:0;background:#e4eedc;border-bottom:1px solid #666;text-align:center;font-size:10px;padding:4px}.officialPhoto{padding:2px;overflow:hidden}.officialReason{border-top:1px solid #666;padding:5px;font-size:9.5px;white-space:pre-wrap;overflow-wrap:anywhere}.officialMeasure{margin-top:8px}.officialVacuum{margin-top:8px}.officialVacuum .officialPhotoCell{grid-template-rows:22px 92px}.officialFooter{position:absolute;left:16mm;right:16mm;bottom:7mm;display:flex;justify-content:space-between;font-size:9px;color:#555}.genericPage{display:block}@page{size:A4;margin:0}@media print{body{background:white}.tools{display:none}.paper{width:210mm;height:297mm;min-height:297mm;margin:0;padding:12mm 15mm 11mm;overflow:hidden}.paper:last-child{break-after:auto}.officialPhotoCell{grid-template-rows:22px 174px minmax(54px,auto)}.officialCriteria.long{font-size:7.2px}}.chillerSourceMeasurementPage .chillerSourceTitle{margin:19px 0 16px;font-size:15px;font-weight:700;text-align:left}.chillerSourceMeasurementPage .chillerSourceTable{margin:0 0 8px;width:100%;table-layout:fixed;border-collapse:collapse}.chillerSourceMeasurementPage .chillerSourceTable th,.chillerSourceMeasurementPage .chillerSourceTable td{border:1px solid #777;padding:3px 5px;font-family:'Malgun Gothic',sans-serif;font-size:10px;line-height:1.2;vertical-align:middle;text-align:center;background:#fff;overflow-wrap:anywhere}.chillerSourceMeasurementPage .chillerSourceTable th{background:#dcebf5;font-weight:600}.chillerSourceMeasurementPage .chillerSourceTable .chillerNumber,.chillerSourceMeasurementPage .chillerSourceTable .chillerMeasured{color:#d34553}.chillerSourceMeasurementPage .chillerSourceTable .chillerNote{text-align:left;font-size:9px}.chillerSourceMeasurementPage .chillerSourceTable .chillerGroupCell{font-weight:500}</style><div class="tools"><button id="printReport">PDF로 저장 / 인쇄</button> A4, 배율 100%, 머리글과 바닥글 해제를 권장합니다.</div>${report()}<script>document.getElementById('printReport').onclick=async()=>{await Promise.all(Array.from(document.images).map(i=>i.decode().catch(()=>{})));window.print()};<\/script></html>`);w.document.close()}
function enhanceVacuumPumpReport(html){const doc=new DOMParser().parseFromString(`<main id="vacuumReportRoot">${html}</main>`,'text/html'),rootNode=doc.getElementById('vacuumReportRoot');for(const e of d.equipment.filter(x=>x.type==='냉동기'))for(const item of e.items.filter(x=>isVacuumPumpItem(e,x))){const expected=`${e.type} · ${e.number} / ${item.title}`,paper=[...rootNode.querySelectorAll('.paper')].find(node=>node.querySelector('h2')?.textContent===expected);if(!paper)continue;paper.style.breakInside='avoid';paper.style.pageBreakInside='avoid';paper.querySelectorAll('.photos .reportPhotoFrame,.photos .noPhoto').forEach(node=>node.style.height='105px');paper.querySelectorAll('.photos p').forEach(node=>{node.style.fontSize='10px';node.style.margin='0';node.style.padding='4px'});const block=doc.createElement('section');block.className='vacuumPumpPrint';block.style.cssText='margin:8px 0;break-inside:avoid;page-break-inside:avoid';const labels=['진공펌프 현황사진','진공펌프 적합 사진','진공펌프 미흡사항 사진'];block.innerHTML=`<h3 style="font-size:13px;margin:4px 0;background:#e4eef5;padding:5px;text-align:center">진공펌프 추가 사진</h3><div style="display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0">${labels.map((label,index)=>{const src=item.photos?.[index+3]||'';return `<section style="border:1px solid #777;min-width:0"><h4 style="font-size:11px;margin:0;text-align:center;background:#e4eef5;padding:4px">${label}</h4>${src?`<div class="reportPhotoFrame" style="height:105px"><img src="${src}" alt="${label}"></div>`:`<div class="noPhoto" style="height:105px">사진 미첨부</div>`}</section>`}).join('')}</div>`;const tables=paper.querySelectorAll('table');tables.length?paper.insertBefore(block,tables[tables.length-1]):paper.appendChild(block)}return rootNode.innerHTML}
const reportWithoutVacuumPhotos=report;report=function(){return enhanceVacuumPumpReport(reportWithoutVacuumPhotos())};
function enhanceReasonReport(html){const doc=new DOMParser().parseFromString(`<main id="reasonReportRoot">${html}</main>`,'text/html'),rootNode=doc.getElementById('reasonReportRoot');for(const e of d.equipment)for(const item of e.items){const expected=`${e.type} · ${e.number} / ${item.title}`,paper=[...rootNode.querySelectorAll('.paper')].find(node=>node.querySelector('h2')?.textContent===expected);if(!paper)continue;const sections=paper.querySelectorAll('.photos>section');sections.forEach(section=>{section.style.display='flex';section.style.flexDirection='column';section.querySelector('h4')?.style.setProperty('border-bottom','1px solid #777')});sections[0]?.querySelector('p')?.remove();const statusPhoto=sections[0]?.querySelector('.reportPhotoFrame,.noPhoto');if(statusPhoto){statusPhoto.style.flex='1 1 auto';statusPhoto.style.height='auto';statusPhoto.style.minHeight='190px'}[1,2].forEach(index=>{const paragraph=sections[index]?.querySelector('p'),key='reason'+index,value=reasonValue(item,key);if(paragraph&&!value)paragraph.remove();else if(paragraph){paragraph.style.borderTop='1px solid #777';paragraph.innerHTML=`사유: ${E(value).replace(/\n/g,'<br>')}`}})}return rootNode.innerHTML}
const reportWithoutReasonEnhancement=report;report=function(){return enhanceReasonReport(reportWithoutReasonEnhancement())};
function officialHeader(){return `<div class="paperhead">${E(d.info['현장명']||'기계설비 성능점검 결과보고서')}</div>`}
function officialFooter(){return `<div class="officialFooter"><span>기계설비 성능점검 결과보고서</span><span>${E(d.info['보고서번호']||'')}</span></div>`}
function officialPhoto(src,label){return src?`<div class="officialPhoto"><img src="${src}" alt="${E(label)}"></div>`:`<div class="officialPhoto noPhoto">사진 미첨부</div>`}
function officialSummaryPage(e){const startPhoto=e.items.flatMap(item=>item.photos||[]).find(Boolean)||'';return `<section class="paper officialPage">${officialHeader()}<h1 class="officialTitle">${E(e.type)} 성능점검표</h1><table class="officialMeta"><tr><th>점검자</th><td>${E(e['점검자']||d.info['점검자']||'')}</td><th>점검일자</th><td>${E(e['점검일']||d.info['점검시작일']||'')}</td><th>설비번호</th><td>${E(e.number)}</td></tr><tr><th>설치위치<br>(No.)</th><td colspan="5">${E(e['설치위치']||'')}</td></tr></table><table class="officialSummary"><thead><tr><th style="width:9%">구분</th><th>점검내용</th><th style="width:12%">점검결과</th></tr></thead><tbody>${e.items.map((item,index)=>`<tr><td class="group">${index===0?'점검<br>항목':''}</td><td>${E(item.title)}</td><td class="mark">${resultMark(item.result)}</td></tr>`).join('')}</tbody></table><div class="officialAction"><b>&lt; 미흡사항 &gt;</b><br>${E(e.items.filter(item=>item.result==='미흡').map(item=>item.title).join(', '))}</div><div class="officialAction"><b>&lt; 조치필요사항 &gt;</b><br>${E(e.items.filter(item=>item.result==='조치필요').map(item=>`${item.title} ${item.action||''}`).join('\n'))}</div><table class="officialGrid"><tr><th style="width:9%">현장<br>사진</th><td><div class="officialRepresentative">${startPhoto?`<img src="${startPhoto}" alt="현장 대표 사진">`:'사진 미첨부'}</div></td></tr><tr><th>비고</th><td>${E(e['측정값']||'')}</td></tr></table><div class="officialNotes"><b>작성방법</b><br>1. 유지관리지침서와 성능점검 대상 현황표를 참고하여 점검결과를 작성합니다.<br>2. 점검결과에는 적합 ○, 조치필요 ×, 해당없음 /를 표기합니다.<br>3. 현황사진에는 측정사진과 측정데이터를 포함합니다.</div>${officialFooter()}</section>`}
function officialItemPage(e,item,index){const long=String(item.criteria||'').length>500;const vacuum=isVacuumPumpItem(e,item)&&item.photos?.slice(3).some(Boolean);return `<section class="paper officialPage">${officialHeader()}<h2 class="officialItemTitle">${E(item.title)}</h2><table class="officialGrid"><tr><th style="width:9%">구분</th><th>점검내용</th></tr><tr><th>점검<br>방법·기준</th><td class="officialCriteria ${long?'long':''}">${E(item.criteria||'').replace(/\n/g,'<br>')}</td></tr></table><div class="officialPhotoGrid">${['현황 사진','적합','미흡사항'].map((label,photoIndex)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex],label)}<div class="officialReason">${photoIndex===0?'':`사유 : ${E(reasonValue(item,'reason'+photoIndex)).replace(/\n/g,'<br>')}`}</div></section>`).join('')}</div>${vacuum?`<div class="officialVacuum"><b>진공펌프 추가 사진</b><div class="officialPhotoGrid">${['진공펌프 현황사진','진공펌프 적합 사진','진공펌프 미흡사항 사진'].map((label,photoIndex)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex+3],label)}</section>`).join('')}</div></div>`:''}<table class="officialGrid officialMeasure"><tr><th style="width:18%">판정</th><td>${E(item.result||'미작성')} ${resultMark(item.result)}</td></tr><tr><th>측정값 / 확인내용</th><td>${E(item.measurement||'').replace(/\n/g,'<br>')}</td></tr><tr><th>조치사항</th><td>${E(item.action||'').replace(/\n/g,'<br>')}</td></tr></table>${officialFooter()}</section>`}
function officialReport(){let html=page('기계설비 성능점검 보고서',table(fields[0].filter(k=>k!=='제출문').map(k=>[k,d.info[k]||'미입력'])));html+=page('점검완료 제출문','<p>'+E(d.info['제출문']||'미입력').replace(/\n/g,'<br>')+'</p>');html+=page('목차','<ol>'+titles.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol>');html+=page('Ⅰ. 성능점검 계획서',textSections(1));html+=page('Ⅱ. 성능점검 결과보고서',textSections(2));for(const e of d.equipment){html+=officialSummaryPage(e);e.items.forEach((item,index)=>html+=officialItemPage(e,item,index))}html+=page('Ⅳ. 기계설비 시스템 검토',textSections(4));html+=page('Ⅴ. 성능개선 계획 수립',textSections(5));html+=page('Ⅵ. 에너지사용량 분석',textSections(6));return html}
report=officialReport;
function officialLongItemPages(e,item,index){const photoPage=`<section class="paper officialPage">${officialHeader()}<h2 class="officialItemTitle">${E(item.title)} - 사진·판정</h2><div class="officialPhotoGrid">${['현황 사진','적합','미흡사항'].map((label,photoIndex)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[photoIndex],label)}<div class="officialReason">${photoIndex===0?'':`사유 : ${E(reasonValue(item,'reason'+photoIndex)).replace(/\n/g,'<br>')}`}</div></section>`).join('')}</div><table class="officialGrid officialMeasure"><tr><th style="width:18%">판정</th><td>${E(item.result||'미작성')} ${resultMark(item.result)}</td></tr><tr><th>측정값 / 확인내용</th><td>${E(item.measurement||'').replace(/\n/g,'<br>')}</td></tr><tr><th>조치사항</th><td>${E(item.action||'').replace(/\n/g,'<br>')}</td></tr></table>${officialFooter()}</section>`;return `<section class="paper officialPage">${officialHeader()}<h2 class="officialItemTitle">${E(item.title)}</h2><table class="officialGrid"><tr><th style="width:9%">구분</th><th>점검내용</th></tr><tr><th>점검<br>방법·기준</th><td class="officialCriteria long" style="height:auto;min-height:205mm;font-size:8px;line-height:1.24">${E(item.criteria||'').replace(/\n/g,'<br>')}</td></tr></table>${officialFooter()}</section>${photoPage}`}
