function ensureOfficialVacuumSection(html){const doc=new DOMParser().parseFromString(`<main id="officialVacuumRoot">${html}</main>`,'text/html'),output=doc.getElementById('officialVacuumRoot');for(const e of d.equipment.filter(entry=>entry.type==='냉동기'))for(const item of e.items.filter(entry=>isVacuumPumpItem(e,entry))){const page=[...output.querySelectorAll('.officialPage')].find(node=>node.querySelector('.officialItemTitle')?.textContent.trim()===item.title);if(!page||page.querySelector('.officialVacuum'))continue;const block=doc.createElement('div');block.className='officialVacuum';block.innerHTML=`<b>진공펌프 추가 사진</b><div class="officialPhotoGrid">${['진공펌프 현황사진','진공펌프 적합 사진','진공펌프 미흡사항 사진'].map((label,index)=>`<section class="officialPhotoCell"><h4>${label}</h4>${officialPhoto(item.photos?.[index+3],label)}</section>`).join('')}</div>`;const measurement=page.querySelector('.officialMeasure');measurement?page.insertBefore(block,measurement):page.appendChild(block)}return output.innerHTML}
