async function loadSharedReport(){if(sharedReportLoaded)return d;if(sharedReportLoading)return sharedReportLoading;sharedReportLoading=(async()=>{try{status('중앙 보고서 불러오는 중…');const remote=await window.PJT_SHARED_REPORT_LOAD?.();if(remote?.version===2){await window.PJT_APPLY_SHARED_REPORT(remote);status('중앙 보고서 불러옴 · PC와 휴대폰 공유')}else{sharedReportLoaded=true;if(localReportAvailable&&window.PJT_SHARED_REPORT_SAVE)await window.PJT_SHARED_REPORT_SAVE(d);status('저장된 보고서 열림')}return d}catch(error){console.warn('보고서 중앙 자료 불러오기 대기',error);status('이 기기 자료 표시 중 · 중앙 보고서는 다시 열 때 재시도');return d}finally{sharedReportLoading=null}})();return sharedReportLoading}
