/* 측정값표: 선택 셀의 위쪽 행과 왼쪽 열을 사용자 지정으로 고정합니다. */
const measurementFreezeSelections=new Map();
const measurementDialogBodyBeforeFreeze=measurementDialogBody;
measurementDialogBody=function(e){const html=measurementDialogBodyBeforeFreeze(e),fixed=e.measurementFreeze,selected=measurementFreezeSelections.get(e.uid),status=fixed?`현재 기준: ${fixed.row+1}행 ${fixed.col+1}열`:(selected?`선택 기준: ${selected.row+1}행 ${selected.col+1}열`:'표 안에서 고정 기준 셀을 먼저 선택하세요.');return html.replace('<div class="reMeasurementScroll">',`<div class="reMeasurementFreezeBar"><button type="button" data-measure-freeze>틀 고정</button><button type="button" data-measure-unfreeze ${fixed?'':'disabled'}>틀 고정 해제</button><small data-measure-freeze-status>${status}</small></div><div class="reMeasurementScroll">`)};
function clearMeasurementFreezeStyles(table){table?.querySelectorAll('.reFreezeTop,.reFreezeLeft,.reFreezeCorner,.reFreezeSelected').forEach(cell=>{cell.classList.remove('reFreezeTop','reFreezeLeft','reFreezeCorner','reFreezeSelected');cell.style.removeProperty('top');cell.style.removeProperty('left')});table?.classList.remove('reFreezeActive')}
function markMeasurementFreezeSelection(dialog,e){const table=dialog.querySelector('.reMeasurementScroll table'),selection=measurementFreezeSelections.get(e.uid);table?.querySelectorAll('.reFreezeSelected').forEach(cell=>cell.classList.remove('reFreezeSelected'));if(!selection||!table?.tBodies[0]?.rows[selection.row])return;table.tBodies[0].rows[selection.row].cells[selection.col]?.classList.add('reFreezeSelected')}
function applyMeasurementFreeze(dialog,e){const table=dialog.querySelector('.reMeasurementScroll table');if(!table)return;clearMeasurementFreezeStyles(table);markMeasurementFreezeSelection(dialog,e);const fixed=e.measurementFreeze;if(!fixed)return;const allRows=[...table.rows],anchorRow=Math.min(Math.max(Number(fixed.row)+1,1),allRows.length),anchorCol=Math.min(Math.max(Number(fixed.col),0),allRows[0]?.cells.length||0),topOffsets=[],leftOffsets=[];let top=0;for(let rowIndex=0;rowIndex<anchorRow;rowIndex++){topOffsets[rowIndex]=top;top+=allRows[rowIndex].getBoundingClientRect().height}let left=0;for(let colIndex=0;colIndex<anchorCol;colIndex++){leftOffsets[colIndex]=left;left+=allRows[0].cells[colIndex]?.getBoundingClientRect().width||0}allRows.forEach((row,rowIndex)=>[...row.cells].forEach((cell,colIndex)=>{const freezeTop=rowIndex<anchorRow,freezeLeft=colIndex<anchorCol;if(freezeTop){cell.classList.add('reFreezeTop');cell.style.top=`${topOffsets[rowIndex]}px`}if(freezeLeft){cell.classList.add('reFreezeLeft');cell.style.left=`${leftOffsets[colIndex]}px`}if(freezeTop&&freezeLeft)cell.classList.add('reFreezeCorner')}));table.classList.add('reFreezeActive')}
function bindMeasurementFreeze(dialog,e){const table=dialog.querySelector('.reMeasurementScroll table'),status=dialog.querySelector('[data-measure-freeze-status]');if(!table)return;table.addEventListener('click',event=>{const cell=event.target.closest('tbody td');if(!cell)return;const row=cell.parentElement.rowIndex-1,col=cell.cellIndex;measurementFreezeSelections.set(e.uid,{row,col});markMeasurementFreezeSelection(dialog,e);if(status)status.innerHTML=`선택 기준: <strong>${row+1}행 ${col+1}열</strong> · 틀 고정을 누르세요.`});dialog.querySelector('[data-measure-freeze]')?.addEventListener('click',async()=>{const selection=measurementFreezeSelections.get(e.uid);if(!selection)return alert('측정값표에서 고정 기준으로 사용할 셀을 먼저 선택하세요.');e.measurementFreeze={row:selection.row,col:selection.col};await save();applyMeasurementFreeze(dialog,e);const unfreeze=dialog.querySelector('[data-measure-unfreeze]');if(unfreeze)unfreeze.disabled=false;if(status)status.innerHTML=`고정됨: <strong>${selection.row+1}행 ${selection.col+1}열</strong>의 위쪽 행과 왼쪽 열`});dialog.querySelector('[data-measure-unfreeze]')?.addEventListener('click',async event=>{delete e.measurementFreeze;measurementFreezeSelections.delete(e.uid);await save();clearMeasurementFreezeStyles(table);event.currentTarget.disabled=true;if(status)status.textContent='틀 고정이 해제되었습니다. 새 기준 셀을 선택할 수 있습니다.'});requestAnimationFrame(()=>applyMeasurementFreeze(dialog,e))}
const bindMeasurementDialogBeforeFreeze=bindMeasurementDialog;
bindMeasurementDialog=function(dialog,e){bindMeasurementDialogBeforeFreeze(dialog,e);bindMeasurementFreeze(dialog,e)};

/* 냉동기 설계값·측정값 AI 보조판정
 * 수치 비교는 재현 가능한 기준 규칙으로 계산하고, 점검표 사유 문장은 계산근거를 포함해 자동 작성합니다.
 * 최종 적용은 점검자가 결과를 확인한 뒤 수행합니다. */
function aiMeasureNumber(value){const normalized=String(value??'').replace(/,/g,'').replace(/[^0-9+\-.]/g,'');if(!normalized||normalized==='-'||normalized==='.')return null;const number=Number(normalized);return Number.isFinite(number)?number:null}
function aiRound(value,digits=2){return Number(Number(value).toFixed(digits)).toLocaleString('ko-KR',{maximumFractionDigits:digits})}
function chillerAIThreshold(row){const item=String(row.item||''),group=String(row.group||''),unit=String(row.unit||'');
 if(/COP/i.test(item))return{mode:'minRatio',limit:.9,label:'설계 COP의 90% 이상'};
 if(/유량/.test(item))return{mode:'minRatio',limit:.9,label:'설계유량의 90% 이상'};
 if(/전류/.test(item))return{mode:'maxRatio',limit:1,label:'설계·정격전류 이하'};
 if(/동력|소비량/.test(item)&&!/증기소비량/.test(item))return{mode:'maxRatio',limit:1.1,label:'설계값의 110% 이하'};
 if(/열량|가열량|증발열량|응축열량|증기소비량/.test(item))return{mode:'minRatio',limit:.9,label:'설계값의 90% 이상'};
 if(/온도/.test(item)||unit==='℃')return{mode:'tolerance',limit:.1,label:'설계값 대비 ±10% 이내'};
 if(/압력/.test(item)||/Pa|bar|kg\/cm|mmHg/.test(unit))return{mode:'tolerance',limit:.1,label:'설계값 대비 ±10% 이내'};
 if(/전압/.test(item))return{mode:'tolerance',limit:.1,label:'설계값 대비 ±10% 이내'};
 return{mode:'tolerance',limit:.1,label:'설계값 대비 ±10% 이내(기본기준)'}
}
function chillerAITargetIndex(e,row){const item=`${row.group||''} ${row.item||''}`;if(/배기.*온도|배기가스/.test(item))return Math.min(11,e.items.length-1);if(/연료|공급압력|회수온도/.test(item))return Math.min(5,e.items.length-1);if(/전압|전류|동력|소비량/.test(item)&&!/증기소비량/.test(item))return Math.min(13,e.items.length-1);return Math.min(14,e.items.length-1)}
function analyzeChillerMeasurement(e,row,index){const design=aiMeasureNumber(row.design),measured=aiMeasureNumber(row.measured),name=[row.group,row.item].filter(Boolean).join(' · ')||`측정항목 ${index+1}`,targetIndex=chillerAITargetIndex(e,row),targetTitle=e.items[targetIndex]?.title||'점검항목';
 if(design===null||measured===null)return{index,name,targetIndex,targetTitle,status:'검토필요',reason:`${name}은(는) ${design===null?'설계값':measured===null?'측정값':'비교값'}이 입력되지 않아 자동 비교가 불가능함. 관련 자료를 확인하여 점검자가 판정할 필요가 있음.`,basis:'설계값과 측정값 모두 필요',design:row.design||'',measured:row.measured||'',unit:row.unit||''};
 if(design===0)return{index,name,targetIndex,targetTitle,status:'검토필요',reason:`${name}의 설계값이 0으로 입력되어 비율 계산이 불가능함. 설계자료와 입력값을 재확인할 필요가 있음.`,basis:'설계값 0은 비율 판정 제외',design:row.design,measured:row.measured,unit:row.unit||''};
 const rule=chillerAIThreshold(row),ratio=measured/design,difference=measured-design,rate=Math.abs(difference/design),pass=rule.mode==='minRatio'?ratio>=rule.limit:rule.mode==='maxRatio'?ratio<=rule.limit:rate<=rule.limit,status=pass?'적합':'미흡',direction=difference===0?'동일':difference>0?'높음':'낮음',comparison=`설계값 ${aiRound(design)}${row.unit||''} 대비 측정값 ${aiRound(measured)}${row.unit||''}으로 ${aiRound(Math.abs(difference))}${row.unit||''} ${direction}`,percent=`설계값의 ${aiRound(ratio*100,1)}%`;
 const reason=pass?`${name}은(는) ${comparison}(${percent})으로 확인되었으며, 판정기준인 ${rule.label}를 만족하여 적합한 것으로 판단됨.`:`${name}은(는) ${comparison}(${percent})으로 확인되어 판정기준인 ${rule.label}를 충족하지 못함. 운전조건, 계측값 및 관련 계통의 상태를 확인하고 필요한 조치를 실시할 필요가 있음.`;
 return{index,name,targetIndex,targetTitle,status,reason,basis:`${rule.label} · 편차율 ${aiRound(rate*100,1)}%`,design:row.design,measured:row.measured,unit:row.unit||'',ratio:ratio*100}
}
function runChillerAIAnalysis(e){if(e.type!=='냉동기')return[];const rows=measurementRows(e),results=rows.map((row,index)=>analyzeChillerMeasurement(e,row,index));results.forEach(result=>{if(Number.isFinite(result.ratio))rows[result.index].percent=`${aiRound(result.ratio,1)}%`});e.measurementAIResults=results;e.measurementAIAnalyzedAt=new Date().toISOString();return results}
function chillerAIResultsHTML(e){if(e.type!=='냉동기')return'';const results=Array.isArray(e.measurementAIResults)?e.measurementAIResults:[],summary={적합:0,미흡:0,검토필요:0};results.forEach(result=>summary[result.status]=(summary[result.status]||0)+1);return `<section class="reAIAnalysis"><div class="reAIAnalysisHead"><div><b>AI 자동판정 결과</b><small>규칙 계산 + 점검보고서 사유 자동작성 · 점검자 최종 확인 필요</small></div>${results.length?`<div class="reAISummary"><span class="pass">적합 ${summary.적합||0}</span><span class="fail">미흡 ${summary.미흡||0}</span><span class="review">검토 ${summary.검토필요||0}</span></div>`:''}</div>${results.length?`<div class="reAIResultList">${results.map(result=>`<article class="reAIResult ${result.status==='적합'?'pass':result.status==='미흡'?'fail':'review'}"><div class="reAIResultTitle"><b>${E(result.name)}</b><span>${E(result.status)}</span></div><small>적용 대상: ${E(result.targetTitle)} · ${E(result.basis)}</small><p>${E(result.reason)}</p><button type="button" data-ai-apply-row="${result.index}" ${result.status==='검토필요'?'disabled':''}>이 사유를 점검표에 적용</button></article>`).join('')}</div><div class="reAIApplyBar"><p>미흡 항목이 있으면 해당 점검항목은 미흡으로 적용되며, 같은 점검항목의 사유는 하나로 묶어 저장됩니다.</p><button type="button" data-ai-apply-all>판정 결과 전체 적용</button></div>`:'<div class="reAIEmpty">설계값과 측정값을 입력한 후 상단의 <b>AI 자동판정</b>을 누르세요.</div>'}</section>`}
async function applyChillerAIResults(e,results){const usable=results.filter(result=>result.status==='적합'||result.status==='미흡'),groups=new Map();usable.forEach(result=>{const values=groups.get(result.targetIndex)||[];values.push(result);groups.set(result.targetIndex,values)});for(const [targetIndex,values] of groups){const item=e.items[targetIndex];if(!item)continue;const failures=values.filter(value=>value.status==='미흡'),selected=failures.length?failures:values,status=failures.length?'미흡':'적합',key=status==='적합'?'reason1':'reason2',other=key==='reason1'?'reason2':'reason1',reason=selected.map(value=>value.reason).join('\n');item.result=status;item.measurement=values.map(value=>`${value.name}: 설계 ${value.design}${value.unit||''} / 측정 ${value.measured}${value.unit||''}`).join('\n');item[other]='';item[other+'Deleted']=true;await preserveReasonBeforeChange(e,item,key,reason)}await save()}
const measurementDialogBodyBeforeAI=measurementDialogBody;
measurementDialogBody=function(e){let html=measurementDialogBodyBeforeAI(e);if(e.type!=='냉동기')return html;html=html.replace('<button type="button" data-dialog-unit-converter>','<button type="button" class="reAIRun" data-ai-chiller-analyze>AI 자동판정</button><button type="button" data-dialog-unit-converter>');return html.replace('<div class="reDialogFooter">',`${chillerAIResultsHTML(e)}<div class="reDialogFooter">`)};
const bindMeasurementDialogBeforeAI=bindMeasurementDialog;
function ensureChillerAIControls(dialog,e){if(e.type!=='냉동기')return;const tools=dialog.querySelector('.reMeasurementDialogTools');if(tools&&!tools.querySelector('[data-ai-chiller-analyze]')){const button=document.createElement('button');button.type='button';button.className='reAIRun';button.dataset.aiChillerAnalyze='';button.textContent='AI 자동판정';tools.prepend(button)}const footer=dialog.querySelector('.reDialogFooter');if(footer&&!dialog.querySelector('.reAIAnalysis'))footer.insertAdjacentHTML('beforebegin',chillerAIResultsHTML(e))}
bindMeasurementDialog=function(dialog,e){bindMeasurementDialogBeforeAI(dialog,e);if(e.type!=='냉동기')return;ensureChillerAIControls(dialog,e);dialog.querySelectorAll('[data-measure-key="design"],[data-measure-key="measured"]').forEach(input=>input.addEventListener('input',()=>{if(!e.measurementAIResults?.length)return;e.measurementAIResults=[];delete e.measurementAIAnalyzedAt;const panel=dialog.querySelector('.reAIAnalysis');if(panel)panel.outerHTML=chillerAIResultsHTML(e)}));dialog.querySelector('[data-ai-chiller-analyze]')?.addEventListener('click',async()=>{runChillerAIAnalysis(e);await save();dialog.querySelector('.reToolDialogBody').outerHTML=measurementDialogBody(e);bindMeasurementDialog(dialog,e)});dialog.querySelectorAll('[data-ai-apply-row]').forEach(button=>button.onclick=async()=>{const result=e.measurementAIResults?.find(value=>value.index===Number(button.dataset.aiApplyRow));if(!result)return;await applyChillerAIResults(e,[result]);button.textContent='점검표에 적용됨';button.disabled=true});dialog.querySelector('[data-ai-apply-all]')?.addEventListener('click',async()=>{const results=e.measurementAIResults||[];if(!results.some(result=>result.status!=='검토필요'))return alert('점검표에 적용할 수 있는 자동판정 결과가 없습니다.');if(!confirm('AI 자동판정 결과를 냉동기 점검표에 적용할까요?\n\n적용 후에도 점검자가 판정과 사유를 수정할 수 있습니다.'))return;await applyChillerAIResults(e,results);dialog.close();render();if(typeof toast==='function')toast('냉동기 AI 판정 결과를 점검표에 적용했습니다.')})};

/* 흡수식 냉동기(직화) 열량·COP 자동계산 */
const DIRECT_FIRED_HEATING_VALUE=9420;
const DIRECT_FIRED_AUTO_ITEMS=new Set(['증발열량','가열량','COP','응축열량']);
function directFiredRow(e,group,item){return measurementRows(e).find(row=>String(row.group||'')===group&&String(row.item||'')===item)}
function directFiredValue(e,group,item,key){return aiMeasureNumber(directFiredRow(e,group,item)?.[key])}
function setDirectFiredValue(e,group,item,key,value,digits=0){const row=directFiredRow(e,group,item);if(!row)return;row[key]=Number.isFinite(value)?Number(value).toFixed(digits):''}
const MEASUREMENT_THOUSANDS_ITEMS=new Set(['유량','증발열량','가열량','응축열량']);
function measurementThousandsValue(value){const text=String(value??'').trim();if(!text)return'';const number=Number(text.replace(/,/g,''));if(!Number.isFinite(number))return text;const decimals=(text.replace(/,/g,'').split('.')[1]||'').length;return number.toLocaleString('ko-KR',{minimumFractionDigits:decimals,maximumFractionDigits:Math.max(decimals,6)})}
function measurementDisplayValue(row,value){return MEASUREMENT_THOUSANDS_ITEMS.has(String(row?.item||''))?measurementThousandsValue(value):String(value??'')}
function recalculateDirectFiredChiller(e){if(e.type!=='냉동기'||e.equipmentFormat!=='흡수식냉동기(직화)')return false;let changed=false;for(const key of ['design','measured']){const chilledIn=directFiredValue(e,'증발기(냉수)','입구온도',key),chilledOut=directFiredValue(e,'증발기(냉수)','출구온도',key),chilledFlow=directFiredValue(e,'증발기(냉수)','유량',key),fuel=directFiredValue(e,'연료','소비량',key),coolingIn=directFiredValue(e,'응축기(냉각수)','입구온도',key),coolingOut=directFiredValue(e,'응축기(냉각수)','출구온도',key),coolingFlow=directFiredValue(e,'응축기(냉각수)','유량',key);const evaporation=[chilledIn,chilledOut,chilledFlow].every(Number.isFinite)?Math.abs(chilledIn-chilledOut)*chilledFlow*60:NaN,heating=Number.isFinite(fuel)?fuel*DIRECT_FIRED_HEATING_VALUE:NaN,cop=Number.isFinite(evaporation)&&Number.isFinite(heating)&&heating!==0?evaporation/heating:NaN,condensation=[coolingIn,coolingOut,coolingFlow].every(Number.isFinite)?Math.abs(coolingOut-coolingIn)*coolingFlow*60:NaN;const values=[['증발기(냉수)','증발열량',evaporation,0],['연료','가열량',heating,0],['성능','COP',cop,2],['응축기(냉각수)','응축열량',condensation,0]];for(const [group,item,value,digits] of values){const row=directFiredRow(e,group,item),raw=Number.isFinite(value)?Number(value).toFixed(digits):'',next=digits===0?measurementThousandsValue(raw):raw;if(row&&row[key]!==next){row[key]=next;changed=true}}}const fuelRow=directFiredRow(e,'연료','가열량');if(fuelRow&&!String(fuelRow.note||'').trim()){fuelRow.note='도시가스 저위발열량 9,420 kcal/N㎥ 적용';changed=true}return changed}
function refreshDirectFiredCalculatedInputs(dialog,e){measurementRows(e).forEach((row,index)=>{if(!DIRECT_FIRED_AUTO_ITEMS.has(String(row.item||'')))return;for(const key of ['design','measured']){const input=dialog.querySelector(`[data-dialog-measure-row="${index}"][data-measure-key="${key}"]`);if(!input)continue;input.value=row[key]||'';input.readOnly=true;input.classList.add('reAutoCalculated');input.title='관련 온도·유량 또는 연료 소비량으로 자동 계산됩니다.'}})}
function installDirectFiredAutoCalculation(dialog,e){if(e.type!=='냉동기'||e.equipmentFormat!=='흡수식냉동기(직화)')return;const changed=recalculateDirectFiredChiller(e);refreshDirectFiredCalculatedInputs(dialog,e);dialog.querySelectorAll('[data-dialog-measure-row]').forEach(input=>{const row=measurementRows(e)[Number(input.dataset.dialogMeasureRow)],key=input.dataset.measureKey;if(!row||!['design','measured'].includes(key)||DIRECT_FIRED_AUTO_ITEMS.has(String(row.item||'')))return;input.addEventListener('input',async()=>{if(recalculateDirectFiredChiller(e)){refreshDirectFiredCalculatedInputs(dialog,e);e.measurementAIResults=[];delete e.measurementAIAnalyzedAt;const panel=dialog.querySelector('.reAIAnalysis');if(panel)panel.outerHTML=chillerAIResultsHTML(e);await save()}})});if(changed)save()}
const measurementDialogBodyBeforeDirectFired=measurementDialogBody;
measurementDialogBody=function(e){const html=measurementDialogBodyBeforeDirectFired(e);if(e.type!=='냉동기'||e.equipmentFormat!=='흡수식냉동기(직화)')return html;return html.replace('<div class="reMeasurementFreezeBar">','<div class="reDirectFiredFormula"><b>직화식 자동계산</b><span>증발열량 = 냉수유량 × 온도차 × 60</span><span>가열량 = 연료소비량 × 9,420</span><span>COP = 증발열량 ÷ 가열량</span><span>응축열량 = 냉각수유량 × 온도차 × 60</span></div><div class="reMeasurementFreezeBar">')};
const bindMeasurementDialogBeforeDirectFired=bindMeasurementDialog;
bindMeasurementDialog=function(dialog,e){bindMeasurementDialogBeforeDirectFired(dialog,e);installDirectFiredAutoCalculation(dialog,e)};

/* AI 판정 즉시 표시 및 측정값 천 단위 표기 */
function syncMeasurementDialogValues(dialog,e){const rows=measurementRows(e);dialog.querySelectorAll('[data-dialog-measure-row]').forEach(input=>{const row=rows[Number(input.dataset.dialogMeasureRow)],key=input.dataset.measureKey;if(row&&key)row[key]=input.value});recalculateDirectFiredChiller(e)}
function installMeasurementThousands(dialog,e){const rows=measurementRows(e);dialog.querySelectorAll('[data-dialog-measure-row]').forEach(input=>{const row=rows[Number(input.dataset.dialogMeasureRow)],key=input.dataset.measureKey;if(!row||!['design','measured'].includes(key)||!MEASUREMENT_THOUSANDS_ITEMS.has(String(row.item||'')))return;input.value=measurementDisplayValue(row,input.value);input.addEventListener('blur',()=>{const formatted=measurementThousandsValue(input.value);input.value=formatted;row[key]=formatted;save()})})}
function aiJudgingProgress(dialog){dialog.querySelector('.reAIWorking')?.remove();const tools=dialog.querySelector('.reMeasurementDialogTools'),panel=document.createElement('div');panel.className='reAIWorking';panel.setAttribute('role','status');panel.setAttribute('aria-live','polite');panel.innerHTML='<span class="reAISpinner" aria-hidden="true"></span><div><b data-ai-working-title>AI 자동판정 준비 중</b><small data-ai-working-step>입력값을 확인하고 있습니다.</small><span class="reAIProgressTrack"><i data-ai-working-bar></i></span></div>';tools?.closest('.reToolDialogHead')?.insertAdjacentElement('afterend',panel);return panel}
function setAIJudgingProgress(panel,title,step,percent){if(!panel)return;const titleNode=panel.querySelector('[data-ai-working-title]'),stepNode=panel.querySelector('[data-ai-working-step]'),bar=panel.querySelector('[data-ai-working-bar]');if(titleNode)titleNode.textContent=title;if(stepNode)stepNode.textContent=step;if(bar)bar.style.width=`${percent}%`}
const aiProgressPause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function runChillerAIFromDialog(dialog,e,button){const progress=aiJudgingProgress(dialog);try{button.disabled=true;button.textContent='AI 판정 중…';dialog.setAttribute('aria-busy','true');setAIJudgingProgress(progress,'AI 자동판정 실행 중','1/4 입력값을 확인하고 있습니다.',18);await aiProgressPause(140);syncMeasurementDialogValues(dialog,e);setAIJudgingProgress(progress,'AI 자동판정 실행 중','2/4 자동계산 값을 반영하고 있습니다.',43);await aiProgressPause(140);const results=runChillerAIAnalysis(e);setAIJudgingProgress(progress,'AI 자동판정 실행 중','3/4 판정 사유를 작성하고 있습니다.',72);await aiProgressPause(180);setAIJudgingProgress(progress,'AI 자동판정 완료','4/4 결과를 화면에 적용했습니다.',100);await aiProgressPause(260);dialog.removeAttribute('aria-busy');const body=dialog.querySelector('.reToolDialogBody');if(body){body.outerHTML=measurementDialogBody(e);bindMeasurementDialog(dialog,e);dialog.querySelector('.reAIAnalysis')?.scrollIntoView({block:'nearest'})}save().catch(error=>console.error('AI 판정 결과 저장 실패',error));return results}catch(error){console.error('AI 자동판정 실패',error);dialog.removeAttribute('aria-busy');setAIJudgingProgress(progress,'AI 자동판정 실패','입력값을 확인한 후 다시 실행해 주세요.',100);progress?.classList.add('error');alert('AI 자동판정을 실행하지 못했습니다.\n\n'+(error?.message||error));button.disabled=false;button.textContent='AI 자동판정';return[]}}
const bindMeasurementDialogBeforeReliableAI=bindMeasurementDialog;
bindMeasurementDialog=function(dialog,e){bindMeasurementDialogBeforeReliableAI(dialog,e);installMeasurementThousands(dialog,e);if(e.type!=='냉동기')return;const oldButton=dialog.querySelector('[data-ai-chiller-analyze]');if(!oldButton)return;const button=oldButton.cloneNode(true);oldButton.replaceWith(button);button.addEventListener('click',()=>runChillerAIFromDialog(dialog,e,button))};

/* 설계·측정값 독립 페이지 및 점검항목 선택 이동 */
const measurementReturnViews=new Map();
const measurementEditSnapshots=new Map();
function measurementPageUI(e){let body=measurementDialogBody(e);body=body.replace('<div class="reDialogFooter"><button type="button" data-dialog-close>닫기</button></div>','<div class="reDialogFooter reMeasurementPageFooter"><button type="button" data-measurement-cancel>취소</button><button type="button" class="reMeasureSaveClose" data-dialog-close>저장하고 닫기</button></div>');return `<section class="reMeasurementPage" data-measurement-page><div class="reMeasurementPageBack"><button type="button" data-dialog-close>← 이전 화면</button><div><small>성능점검표 · 설계·측정값</small><strong>${E(e.type)} · ${E(e.number)}</strong></div></div>${body}</section>`}
function openMeasurementPage(){const e=equip();if(!e)return;const currentView=equipmentViews.get(e.uid)==='check'?'check':'info';measurementReturnViews.set(e.uid,currentView);measurementEditSnapshots.set(e.uid,{installYear:e['설치년도']||'',rows:structuredClone(measurementRows(e)),aiResults:structuredClone(e.measurementAIResults||[]),aiAnalyzedAt:e.measurementAIAnalyzedAt||''});equipmentViews.set(e.uid,'measurement');render();window.scrollTo({top:root()?.offsetTop||0,behavior:'auto'})}
/* V81: 입력값 반영 후 화면을 먼저 전환합니다. 원격 동기화 지연으로 버튼이 멈춘 것처럼 보이지 않도록 합니다. */
let measurementPageClosing=false;
function closeMeasurementPage(e,cancel=false){
 if(measurementPageClosing)return;
 measurementPageClosing=true;
 try{
  const page=root()?.querySelector('[data-measurement-page]');
  if(!cancel&&page){
   // blur 전 마지막 입력값까지 저장 모델에 동기화
   const year=page.querySelector('[data-dialog-install-year]');
   if(year)e['설치년도']=year.value;
   syncMeasurementDialogValues(page,e);
  }
  if(cancel){
   const snapshot=measurementEditSnapshots.get(e.uid);
   if(snapshot){
    e['설치년도']=snapshot.installYear;
    e.measurementRows=structuredClone(snapshot.rows);
    e.measurementAIResults=structuredClone(snapshot.aiResults);
    if(snapshot.aiAnalyzedAt)e.measurementAIAnalyzedAt=snapshot.aiAnalyzedAt;
    else delete e.measurementAIAnalyzedAt;
   }
  }
  measurementEditSnapshots.delete(e.uid);
  const destination=measurementReturnViews.get(e.uid)||'info';
  equipmentViews.set(e.uid,destination);
  measurementReturnViews.delete(e.uid);
  const pendingSave=save(); // 현재 입력값을 즉시 스냅샷으로 확보
  render();
  const target=destination==='check'?document.getElementById('reSwipePage'):root()?.querySelector('.reEquipmentInfo');
  target?.scrollIntoView({block:'start',behavior:'auto'});
  // 저장은 큐에 넣되, 네트워크 완료 때문에 UI 전환이 차단되지 않도록 처리
  pendingSave.then(()=>{
   if(!cancel&&typeof toast==='function')toast('설계·측정값을 저장했습니다.');
  }).catch(error=>{
   console.error('V81 측정값 저장 실패',error);
   alert('측정값 저장에 실패했습니다. 데이터 연결을 확인하고 다시 저장해 주세요.');
  });
 }catch(error){
  console.error('V81 측정값 화면 전환 실패',error);
  alert('화면을 닫는 중 문제가 발생했습니다: '+(error?.message||error));
 }finally{measurementPageClosing=false;}
}
const measurementDialogBodyBeforePageControls=measurementDialogBody;
measurementDialogBody=function(e){const html=measurementDialogBodyBeforePageControls(e);if(equipmentViews.get(e.uid)!=='measurement')return html;return html.replace('<div class="reDialogFooter"><button type="button" data-dialog-close>닫기</button></div>','<div class="reDialogFooter reMeasurementPageFooter"><button type="button" data-measurement-cancel>취소</button><button type="button" class="reMeasureSaveClose" data-dialog-close>저장하고 닫기</button></div>')};
const bindMeasurementDialogBeforePageControls=bindMeasurementDialog;
bindMeasurementDialog=function(container,e){bindMeasurementDialogBeforePageControls(container,e);if(equipmentViews.get(e.uid)!=='measurement')return;container.querySelectorAll('[data-dialog-close]').forEach(button=>button.onclick=()=>closeMeasurementPage(e,false));container.querySelector('[data-measurement-cancel]')?.addEventListener('click',()=>closeMeasurementPage(e,true))};
function bindMeasurementPage(e){const page=root()?.querySelector('[data-measurement-page]');if(!page)return;page.close=()=>closeMeasurementPage(e,false);bindMeasurementDialog(page,e)}
const equipmentCheckUIBeforeQuickNavigation=equipmentCheckUI;
equipmentCheckUI=function(e){return equipmentCheckUIBeforeQuickNavigation(e).replace('<button type="button" data-show-info>← 기본정보·현장사진</button>','<div class="reCheckHeadActions"><button type="button" class="reCheckMeasurement" data-measure-edit>설계·측정값 입력·수정</button><button type="button" data-show-info>← 기본정보·현장사진</button></div>')};
const pagerBeforeItemJump=pager;
pager=function(e,i){const original=pagerBeforeItemJump(e,i),options=e.items.map((item,index)=>`<option value="${index}" ${index===i?'selected':''}>${index+1}. ${E(item.title)}</option>`).join('');return original.replace('<span role="status"',`<label class="reItemJump"><select data-item-jump aria-label="이동할 점검항목 선택">${options}</select></label><span role="status"`)};
const bindPagerBeforeItemJump=bindPager;
bindPager=function(){bindPagerBeforeItemJump();root().querySelectorAll('[data-item-jump]').forEach(select=>select.addEventListener('change',()=>{const e=equip(),next=Number(select.value);if(!e||!Number.isInteger(next)||next<0||next>=e.items.length)return;itemPositions.set(e.uid,next);render();document.getElementById('reSwipePage')?.scrollIntoView({block:'start',behavior:'auto'})}))};
const equipmentUIBeforeMeasurementPage=equipmentUI;
equipmentUI=function(){const e=equip();return e&&equipmentViews.get(e.uid)==='measurement'?measurementPageUI(e):equipmentUIBeforeMeasurementPage()};
const bindBeforeMeasurementPage=bind;
bind=function(){bindBeforeMeasurementPage();const e=equip();if(e&&equipmentViews.get(e.uid)==='measurement'){bindMeasurementPage(e);return}root().querySelectorAll('[data-measure-edit]').forEach(button=>{const replacement=button.cloneNode(true);button.replaceWith(replacement);replacement.addEventListener('click',openMeasurementPage)})};

const measurementOfficialPageBeforeThousands=measurementOfficialPage;
measurementOfficialPage=function(e){let html=measurementOfficialPageBeforeThousands(e);for(const row of measurementRows(e)){for(const key of ['design','measured']){const raw=String(row[key]??''),formatted=measurementDisplayValue(row,raw);if(raw&&formatted!==raw)html=html.replace(`>${E(raw)}<`,`>${E(formatted)}<`)}}return html};
const buildExcelMeasurementBeforeThousands=buildExcelMeasurement;
buildExcelMeasurement=async function(wb,e,equipmentIndex){await buildExcelMeasurementBeforeThousands(wb,e,equipmentIndex);const ws=wb.worksheets[wb.worksheets.length-1],rows=measurementRows(e);rows.forEach((row,index)=>{if(!MEASUREMENT_THOUSANDS_ITEMS.has(String(row.item||'')))return;for(const col of [4,6]){const cell=ws.getCell(7+index,col),number=aiMeasureNumber(col===4?row.design:row.measured);if(number!==null){cell.value=number;cell.numFmt='#,##0.######'}}})};

/* 흡수식냉동기(직화) 측정값표 입력/자동계산 가독성 */
function installDirectFiredReadability(container,e){
 if(e.type!=='냉동기'||e.equipmentFormat!=='흡수식냉동기(직화)')return;
 const scroll=container.querySelector('.reMeasurementScroll');
 if(scroll&&!container.querySelector('.reMeasurementLegend'))scroll.insertAdjacentHTML('beforebegin','<div class="reMeasurementLegend" role="note" aria-label="입력칸 구분 안내"><b>입력칸 안내</b><span class="manual">직접 입력</span><span class="automatic">자동 계산 · 수정 불가</span><span class="result">자동 표시 결과</span><small>노란색 설계값·측정값 칸만 입력하면 열량과 COP가 자동 계산됩니다.</small></div>');
 const rows=measurementRows(e);
 let previousGroup='';
 container.querySelectorAll('.reMeasurementScroll tbody tr').forEach((tr,index)=>{
  const row=rows[index];if(!row)return;
  const automatic=DIRECT_FIRED_AUTO_ITEMS.has(String(row.item||''));
  tr.classList.add(automatic?'reMeasureRowAutomatic':'reMeasureRowManual');
  if(index&&row.group!==previousGroup)tr.classList.add('reMeasureGroupStart');
  previousGroup=row.group;
  ['design','measured'].forEach(key=>{
   const input=tr.querySelector(`[data-measure-key="${key}"]`);if(!input)return;
   const cell=input.closest('td');
   cell?.classList.add(automatic?'reMeasureAutoCell':'reMeasureInputCell');
   if(automatic){input.readOnly=true;input.setAttribute('aria-label',`${row.item} ${key==='design'?'설계':'측정'} 자동 계산값`);if(cell&&!cell.querySelector('.reMeasureCellBadge'))cell.insertAdjacentHTML('beforeend','<small class="reMeasureCellBadge">자동 계산</small>')}
   else{input.placeholder='입력';input.setAttribute('aria-label',`${row.item} ${key==='design'?'설계값':'측정값'} 직접 입력`)}
  });
  const percent=tr.querySelector('[data-measure-key="percent"]');
  if(percent){percent.readOnly=true;percent.closest('td')?.classList.add('reMeasureResultCell');percent.setAttribute('aria-label',`${row.item} 자동 계산 비율`)}
 });
}
const bindMeasurementDialogBeforeReadability=bindMeasurementDialog;
bindMeasurementDialog=function(container,e){bindMeasurementDialogBeforeReadability(container,e);installDirectFiredReadability(container,e)};

/* 측정값표 틀 고정 제거 및 모바일 카드형 표시 */
const measurementDialogBodyBeforeMobileCards=measurementDialogBody;
measurementDialogBody=function(e){
 const html=measurementDialogBodyBeforeMobileCards(e);
 return html.replace(/<div class="reMeasurementFreezeBar">[\s\S]*?<\/div>(?=<div class="reMeasurementScroll">)/,'');
};
bindMeasurementFreeze=function(dialog,e){
 delete e.measurementFreeze;
 measurementFreezeSelections.delete(e.uid);
 clearMeasurementFreezeStyles(dialog.querySelector('.reMeasurementScroll table'));
};

/* V80: 원본 냉동기 점검표 13~16쪽과 같은 5열 측정표, 설비별 마지막 페이지에 추가.
 * 기존 사진·사유·조치사항/데이터 모델은 변경하지 않습니다. */
const CHILLER_PRINT_NAMES={
 '일반냉동기':'일반냉동기',
 '흡수식냉동기(중온수)':'흡수식냉동기',
 '흡수식냉동기(증기)':'흡수식냉동기',
 '흡수식냉동기(직화)':'흡수식냉온수기'
};
const chillerMeasurementBeforeV80=measurementOfficialPage;
const excelMeasurementBeforeV80=buildExcelMeasurement;
function chillerPrintValue(v){return E(v===undefined||v===null?'':String(v))}
function chillerPrintRows(e){
 const format=e.equipmentFormat, template=CHILLER_MEASUREMENTS[format];
 if(!template)return null;
 const saved=measurementRows(e);
 const lookup=new Map(saved.map(r=>[`${r.group}|||${r.item}`,r]));
 return template.map(([group,item,unit])=>{
  if(item==='설치년도')return {group:'',item,unit,design:'',measured:e['설치년도']||'',percent:'',note:''};
  const row=lookup.get(`${group}|||${item}`)||{};
  return {group,item,unit,design:row.design||'',measured:row.measured||'',percent:row.percent||'',note:row.note||''};
 });
}
function chillerPrintGroup(group){return group==='기본'?'':group==='성능'?'':group.replace(/\(/g,'<br>(')}
function chillerPrintItem(row){return `${chillerPrintValue(row.item)}${row.unit?`(${chillerPrintValue(row.unit)})`:''}`}
measurementOfficialPage=function(e){
 if(e.type!=='냉동기'||!CHILLER_PRINT_NAMES[e.equipmentFormat])return chillerMeasurementBeforeV80(e);
 const rows=chillerPrintRows(e),type=CHILLER_PRINT_NAMES[e.equipmentFormat];
 let groupHtml='';
 for(let i=0;i<rows.length;){
  const group=rows[i].group;let end=i+1;
  while(end<rows.length&&rows[end].group===group)end++;
  rows.slice(i,end).forEach((r,j)=>{
   const groupCell=j===0?`<td class="chillerGroupCell" rowspan="${end-i}">${chillerPrintGroup(group)}</td>`:'';
   groupHtml+=`<tr>${groupCell}<td class="chillerItemCell">${chillerPrintItem(r)}</td><td>${chillerPrintValue(r.design)}</td><td class="chillerMeasured">${chillerPrintValue(r.measured)}</td><td>${chillerPrintValue(r.percent)}</td><td class="chillerNote">${chillerPrintValue(r.note)}</td></tr>`;
  });i=end;
 }
 return `<section class="paper officialPage officialMeasurementPage chillerSourceMeasurementPage">${officialHeader()}<h2 class="chillerSourceTitle">&lt;${E(type)}&gt;</h2><table class="officialGrid chillerSourceTable"><colgroup><col style="width:15%"><col style="width:24%"><col style="width:19%"><col style="width:19%"><col style="width:10%"><col style="width:13%"></colgroup><thead><tr><th colspan="6" class="chillerNumber">${E(e.number)}</th></tr><tr><th colspan="2">구분</th><th>설계</th><th>측정</th><th>%</th><th>비고</th></tr></thead><tbody>${groupHtml}</tbody></table>${officialFooter()}</section>`;
};
/* 표의 첫 두 열을 원본과 같이 묶어 표시하되 데이터는 행별로 유지 */
function styleChillerExcelCell(cell,head=false){
 cell.font={name:'Malgun Gothic',size:head?10:9,bold:head,color:{argb:'FF111111'}};
 cell.alignment={horizontal:'center',vertical:'middle',wrapText:true};
 const edge={style:'thin',color:{argb:'FF7A7A7A'}};
 cell.border={top:edge,bottom:edge,left:edge,right:edge};
 if(head)cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFDCEBF5'}};
}
buildExcelMeasurement=async function(wb,e,equipmentIndex){
 if(e.type!=='냉동기'||!CHILLER_PRINT_NAMES[e.equipmentFormat])return excelMeasurementBeforeV80(wb,e,equipmentIndex);
 const rows=chillerPrintRows(e),type=CHILLER_PRINT_NAMES[e.equipmentFormat];
 const ws=wb.addWorksheet(safeSheetName(`${e.number}_측정값`,`설비${equipmentIndex+1}_측정값`));
 setupExcelSheet(ws);
 ws.columns=[{width:13},{width:23},{width:18},{width:18},{width:11},{width:23}];
 ws.pageSetup={...ws.pageSetup,fitToPage:true,fitToWidth:1,fitToHeight:1,orientation:'portrait',paperSize:9};
 ws.mergeCells('A2:F2');ws.getCell('A2').value=`<${type}>`;
 ws.getCell('A2').font={name:'Malgun Gothic',size:13,bold:true};ws.getCell('A2').alignment={horizontal:'left',vertical:'middle'};
 ws.getRow(2).height=28;
 ws.mergeCells('A4:F4');ws.getCell('A4').value=e.number;
 ws.getCell('A4').font={name:'Malgun Gothic',size:12,bold:true,color:{argb:'FFDA4B58'}};
 ws.getCell('A4').alignment={horizontal:'center',vertical:'middle'};
 ws.getRow(4).height=23;
 ws.mergeCells('A5:B5');
 [['A5','구분'],['C5','설계'],['D5','측정'],['E5','%'],['F5','비고']].forEach(([pos,label])=>{const c=ws.getCell(pos);c.value=label;styleChillerExcelCell(c,true)});
 ws.getRow(5).height=24;
 let index=0,rownum=6;
 while(index<rows.length){const group=rows[index].group;let end=index+1;while(end<rows.length&&rows[end].group===group)end++;
  if(group!=='기본'&&group!=='성능'&&end-index>1)ws.mergeCells(rownum,1,rownum+(end-index)-1,1);
  for(let j=index;j<end;j++){
   const r=rows[j],n=rownum+j-index;
   if(j===index)ws.getCell(n,1).value=group==='기본'||group==='성능'?'':group;
   ws.getCell(n,2).value=`${r.item}${r.unit?'('+r.unit+')':''}`;
   ws.getCell(n,3).value=r.design;ws.getCell(n,4).value=r.measured;
   ws.getCell(n,5).value=r.percent;ws.getCell(n,6).value=r.note;
   for(let k=1;k<=6;k++)styleChillerExcelCell(ws.getCell(n,k));
   ws.getCell(n,4).font={name:'Malgun Gothic',size:9,color:{argb:'FFD34553'}};
   ws.getRow(n).height=24;
  }rownum+=end-index;index=end;
 }
 ws.pageSetup.printArea=`A2:F${rownum-1}`;
};
/* 각 냉동기의 요약/항목이 끝나는 즉시 해당 기종 측정표 삽입 */
report=function(){
 let html=page('기계설비 성능점검 보고서',table(fields[0].filter(k=>k!=='제출문').map(k=>[k,d.info[k]||'미입력'])));
 html+=page('점검완료 제출문','<p>'+E(d.info['제출문']||'미입력').replace(/\n/g,'<br>')+'</p>');
 html+=page('목차','<ol>'+titles.map(t=>'<li>'+E(t)+'</li>').join('')+'</ol>');
 html+=page('Ⅰ. 성능점검 계획서',textSections(1));
 html+=page('Ⅱ. 성능점검 결과보고서',textSections(2));
 for(const e of d.equipment){html+=equipmentOfficialPagesBeforeMeasurement(e);if(e.type==='냉동기')html+=measurementOfficialPage(e)}
 html+=page('Ⅳ. 기계설비 시스템 검토',textSections(4));
 html+=page('Ⅴ. 성능개선 계획 수립',textSections(5));
 html+=page('Ⅵ. 에너지사용량 분석',textSections(6));
 for(const e of d.equipment.filter(e=>e.type!=='냉동기'))html+=measurementOfficialPage(e);
 return html;
};
exportInspectionExcel=async function(){
 if(!d.equipment.length)return alert('먼저 성능점검표에서 설비와 점검내용을 등록하세요.');
 if(!window.ExcelJS)return alert('Excel 출력 구성요소를 불러오지 못했습니다. 인터넷 연결 후 다시 시도하세요.');
 try{
  status('냉동기 원본 양식 기반 Excel 점검표 생성 중…');
  const wb=new ExcelJS.Workbook();wb.creator='기계설비 성능점검';wb.created=new Date();
  for(let idx=0;idx<d.equipment.length;idx++){
   const e=d.equipment[idx];await buildExcelSummary(wb,e,idx);
   for(let k=0;k<e.items.length;k++)await buildExcelItem(wb,e,e.items[k],k,idx);
   if(e.type==='냉동기')await buildExcelMeasurement(wb,e,idx);
  }
  for(let idx=0;idx<d.equipment.length;idx++)if(d.equipment[idx].type!=='냉동기')await buildExcelMeasurement(wb,d.equipment[idx],idx);
  const buffer=await wb.xlsx.writeBuffer();
  download(buffer,`${fileName()}_성능점검표.xlsx`,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
  status('Excel 점검표 출력 완료');
 }catch(error){console.error(error);status('Excel 점검표 출력 실패');alert('Excel 점검표를 만들지 못했습니다.\n\n'+(error?.message||error))}
};


